var app = angular.module('genboe', ['ngAnimate', 'ngSanitize', 'ui.grid', 'ui.grid.edit', 'ui.grid.cellNav', 'ui.grid.resizeColumns', 'ui.grid.pagination', 'ui.bootstrap', 'ngCookies', 'gen.directives', 'MoqEquationApp', 'ui.tinymce', 'ui.sortable'])

// Intercept ajax responses for global error handling.
.factory('globalErrorInterceptor', ['$q', function ($q) {
    return {
        responseError: function (response) {

            if (response.data !== null && response.data !== undefined && response.data.ReturnType != 'GenValidationException') {
                var error = {};
                error.Title = response.data.Title;
                error.Message = response.data.Message;
                error.Details = response.data.Details;

                DisplayExceptionDialog(error);
            }

            return $q.reject(response);
        }
    };
}])

.config(['$httpProvider', function ($httpProvider) {
    // Include this header with all ajax calls made by $http.  This allows "Request.IsAjaxRequest()" to work on the server.
    $httpProvider.defaults.headers.common['X-Requested-With'] = 'XMLHttpRequest';

    $httpProvider.interceptors.push('globalErrorInterceptor');
}])

.animation('.vertical-slide', function () {
    return {
        addClass: function (element, done) {
            element.animate({ height: 'hide' }, 600, 'swing', done);
        },
        removeClass: function (element, done) {
            element.removeClass('ng-hide');
            element.animate({ height: 'show' }, 600, 'swing', done);
        }
    };
});

